    @Test func compressedBits() {
        let mismatches = Mismatches("portCompressedBitsI8InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0x801D_F67F_478E_2357)
        let bitsInputs = Inputs.buffers(
            UInt8.self,
            count: (H.laneCount + 7) / 8,
            seed: 0x801D_F57F_478E_21A4
        )
        for (a, bits) in everyPair(aInputs, bitsInputs) {
            let (portResult, referenceResult) = bits.withUnsafeBufferPointer { source in
                (
                    { () -> SIMD<Int8> in
                        var a = a
                        return withUnsafeTemporaryAllocation(of: SIMD<Int8>.self, capacity: 1) {
                            result in
                            unsafe portCompressedBitsI8InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                &a,
                                bits: source.baseAddress!
                            )
                            return unsafe result.baseAddress.unsafelyUnwrapped.move()
                        }
                    }(),
                    (bits + [UInt8](repeating: 0, count: 8)).withUnsafeBufferPointer { padded in
                        { () -> SIMD<Int8> in
                            var a = a
                            return withUnsafeTemporaryAllocation(of: SIMD<Int8>.self, capacity: 1) {
                                result in
                                unsafe highwayCompressedBitsI8InVectorCode(
                                    result.baseAddress.unsafelyUnwrapped,
                                    &a,
                                    bits: padded.baseAddress!
                                )
                                return unsafe result.baseAddress.unsafelyUnwrapped.move()
                            }
                        }()
                    }
                )
            }
            let checkedLanes = compressedLaneCount(
                bits: bits,
                lanes: H.laneCount,
                tailIsDeterministic: HighwayReference.compressTailIsDeterministicI8()
            )
            mismatches.check(
                (0..<checkedLanes).map { portResult.simd[$0] },
                (0..<checkedLanes).map { referenceResult.simd[$0] },
                "a: \(describe(a)), bits: \(describe(bits))"
            )
        }
        mismatches.record()
    }

